from tools fetch numbers

const SIDES = 6
player = input("Player name: ") or "Player"
targets = [2, 4, 4]
targets.add(3, 1)
targets.remove(0)
targets.replace(4, 5)

function play(target) {
    roll = randomInt(1, SIDES)
    if (roll >= target) {
        print(color.green(f"Hit! Rolled {roll}, needed {target}."))
        return numbers.double(roll)
    }
    print(f"{color.red('Miss!')} Rolled {roll}, needed {target}.")
    return 0
}

print(color.cyan(f"""Dice Dash: {player}
Beat or match each target to score points."""))

points = 0
for (target in targets) {
    points += play(target)
    wait(0.15)
}
print(f"{player} scored {points} points in {length(targets)} rolls.")
